// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n, uint64 ts) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.setL1BlockValues(n, ts, 1, bytes32(0), 0, bytes32(0), 0, 0) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && address(c).balance == balBefore);
    }

    function testFuzz_run(uint64 n, uint64 ts) public {
        _run(n, ts);
    }

    receive() external payable {}
}
